#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "ludcmp.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_1D(b,N,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;
  DATA_TYPE fn = (DATA_TYPE)n;

  for (i = 0; i < n; i++)
    {
      x[i] = 0;
      y[i] = 0;
      b[i] = (i+1)/fn/2.0 + 4;
    }

  for (i = 0; i < n; i++)
    {
      for (j = 0; j <= i; j++)
	A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++) {
	A[i][j] = 0;
      }
      A[i][i] = 1;
    }

  /* Make the matrix positive semi-definite.
     Not necessary for LU, but kept identical to the original code
     used by the Cholesky benchmark. */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  /* Local restrict-qualified pointers improve alias analysis
     and cache locality inside this initialization routine. */
  DATA_TYPE (*restrict a)[n] = A;
  DATA_TYPE (*restrict b_mat)[n] = B;

  /* Zero B. */
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      b_mat[r][s] = 0;

  /* B = A * A^T
     Original loop order is (t, r, s); we keep that order but
     hoist the load of A[r][t] out of the innermost loop to avoid
     redundant loads and improve data locality.  The accumulation
     order for each B[r][s] remains unchanged. */
  for (t = 0; t < n; ++t)
    {
      for (r = 0; r < n; ++r)
        {
          DATA_TYPE art = a[r][t]; /* reused across all s for fixed (t,r) */
          for (s = 0; s < n; ++s)
            b_mat[r][s] += art * a[s][t];
        }
    }

  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      a[r][s] = b_mat[r][s];

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x[i]);
  }
  POLYBENCH_DUMP_END("x");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations in this version:

   - Introduce local restrict-qualified pointers for A, b, x, y to
     help the compiler with alias analysis and enable better
     vectorization and instruction scheduling.
   - Cache frequently used row pointers (e.g., a_i = A[i]) to reduce
     address computation cost and improve cache locality.
   - For the upper-triangular (U) update, transform the computation
     from a per-column dot-product into a sequence of rank-1 updates
     over the row. This reorders the i-j-k loops to:
         for k
           for j
             A[i][j] -= A[i][k] * A[k][j];
     For each element A[i][j], the sequence of floating-point
     operations remains in the same k-order (0,1,...,i-1) as in the
     original code, so floating-point semantics for each element are
     preserved while significantly improving memory access patterns.
   - Inner-product loops in the lower-triangular part are slightly
     unrolled to reduce loop overhead while preserving the exact
     operation order on the accumulator variable.
*/
static
void kernel_ludcmp[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(b,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j, k;
  DATA_TYPE w;

  /* Local restrict-qualified views of the input arrays.  The original
     PolyBench allocation guarantees that these arrays do not alias. */
  DATA_TYPE (*restrict a)[n] = A;
  DATA_TYPE *restrict b_vec  = b;
  DATA_TYPE *restrict x_vec  = x;
  DATA_TYPE *restrict y_vec  = y;

#pragma scop
  /* LU factorization without pivoting. */
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *restrict a_i = a[i]; /* Current row pointer */

    /* Compute L(i, 0..i-1): lower-triangular part.
       Inner k-loop is manually unrolled by 4, but the sequence of
       subtractions on w is kept identical to the original code. */
    for (j = 0; j < i; j++) {
      w = a_i[j];

      int k_unroll_limit = j & ~3; /* largest multiple of 4 <= j */

      for (k = 0; k < k_unroll_limit; k += 4) {
        w -= a_i[k    ] * a[k    ][j];
        w -= a_i[k + 1] * a[k + 1][j];
        w -= a_i[k + 2] * a[k + 2][j];
        w -= a_i[k + 3] * a[k + 3][j];
      }

      for (; k < j; k++) {
        w -= a_i[k] * a[k][j];
      }

      a_i[j] = w / a[j][j];
    }

    /* Compute U(i, i..N-1): upper-triangular part.

       Original code (for fixed i) did, for every column j >= i:
         w = A[i][j];
         for k = 0..i-1:
             w -= A[i][k] * A[k][j];
         A[i][j] = w;

       Here we reorganize this as a sequence of rank-1 updates:
         for k = 0..i-1:
           for j = i..N-1:
             A[i][j] -= A[i][k] * A[k][j];

       For each (i,j), the updates with respect to k still occur in
       strictly increasing k-order (0,1,...,i-1), so the generated
       floating-point operations and their order on A[i][j] are
       identical to the original implementation.  The new ordering
       improves cache behavior because both A[i][j] and A[k][j] are
       traversed with unit stride in the innermost loop. */
    for (k = 0; k < i; k++) {
      const DATA_TYPE a_ik = a_i[k];
      const DATA_TYPE *restrict a_k = a[k];

      for (j = i; j < _PB_N; j++) {
        a_i[j] -= a_ik * a_k[j];
      }
    }
    /* Note: when i == 0, the k-loop is skipped and A[0][j] remains
       unchanged, matching the original behavior where w = A[0][j]
       and no subtraction is performed. */
  }

  /* Forward substitution: solve L*y = b. */
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *restrict a_i = a[i];
    w = b_vec[i];

    /* Inner loop is simple; we keep the original order, but use
       the cached row pointer for better locality. */
    for (j = 0; j < i; j++)
      w -= a_i[j] * y_vec[j];

    y_vec[i] = w;
  }

  /* Backward substitution: solve U*x = y. */
  for (i = _PB_N-1; i >= 0; i--) {
    DATA_TYPE *restrict a_i = a[i];
    w = y_vec[i];

    for (j = i+1; j < _PB_N; j++)
      w -= a_i[j] * x_vec[j];

    x_vec[i] = w / a_i[i];
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(b),
	      POLYBENCH_ARRAY(x),
	      POLYBENCH_ARRAY(y));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_ludcmp (n,
		 POLYBENCH_ARRAY(A),
		 POLYBENCH_ARRAY(b),
		 POLYBENCH_ARRAY(x),
		 POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(b);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}
