#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "ludcmp.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_1D(b,N,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;
  DATA_TYPE fn = (DATA_TYPE)n;

  /* Initialize vectors. */
  for (i = 0; i < n; i++)
    {
      x[i] = 0;
      y[i] = 0;
      b[i] = (i+1)/fn/2.0 + 4;
    }

  /* Initialize A as a lower-triangular-like matrix with unit diagonal. */
  for (i = 0; i < n; i++)
    {
      DATA_TYPE *Ai = A[i]; /* Row pointer for better locality. */

      for (j = 0; j <= i; j++)
	Ai[j] = (DATA_TYPE)(-j % n) / n + 1;

      for (j = i+1; j < n; j++)
	Ai[j] = 0;

      Ai[i] = 1;
    }

  /* Make the matrix positive semi-definite.
     Not necessary for LU itself, but preserved to match the original
     PolyBench initialization (shared with the Cholesky benchmark). */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  /* Treat B as a flat 1D buffer to simplify index arithmetic and to
     allow more efficient row-wise access. */
  DATA_TYPE *B1 = (DATA_TYPE*)POLYBENCH_ARRAY(B);

  /* Zero-initialize B. */
  for (r = 0; r < n; ++r)
    {
      DATA_TYPE *Br = B1 + r * n;
      for (s = 0; s < n; ++s)
        Br[s] = 0;
    }

  /* Compute B = A * A^T.
     Original code:
       for t
         for r
           for s
             B[r][s] += A[r][t] * A[s][t];
     We keep the same loop order but reuse A[r][t] across the inner loop
     and access B row-contiguously via Br. */
  for (t = 0; t < n; ++t)
    {
      for (r = 0; r < n; ++r)
        {
          DATA_TYPE *Br = B1 + r * n;
          const DATA_TYPE Art = A[r][t]; /* Reuse this across s. */

          for (s = 0; s < n; ++s)
            Br[s] += Art * A[s][t];
        }
    }

  /* Copy B back into A. */
  for (r = 0; r < n; ++r)
    {
      DATA_TYPE *Ar = A[r];
      DATA_TYPE *Br = B1 + r * n;

      for (s = 0; s < n; ++s)
        Ar[s] = Br[s];
    }

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x[i]);
  }
  POLYBENCH_DUMP_END("x");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_ludcmp[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(b,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j, k;
  DATA_TYPE w;

#pragma scop
  /* LU factorization without pivoting.
     The structure is:
       - First, compute row i of L (columns < i).
       - Then, compute row i of U (columns >= i).
  */
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE *Ai = A[i]; /* Current row of A (will hold L and U). */

      /* Compute L(i, j) for j < i (strictly lower triangular part).
         This is the usual left-looking update:
           L(i,j) = (A(i,j) - sum_{k<j} L(i,k)*U(k,j)) / U(j,j)
      */
      for (j = 0; j < i; j++)
        {
          w = Ai[j];

          for (k = 0; k < j; k++)
            w -= Ai[k] * A[k][j];

          Ai[j] = w / A[j][j];
        }

      /* Compute U(i, j) for j >= i (upper-triangular part).
         Original formulation:

           for (j = i; j < N; j++) {
             w = A[i][j];
             for (k = 0; k < i; k++)
               w -= A[i][k] * A[k][j];
             A[i][j] = w;
           }

         This is equivalent to:
           for (j = i; j < N; j++)
             for (k = 0; k < i; k++)
               A[i][j] -= A[i][k] * A[k][j];

         We now interchange the loops over j and k to improve data
         locality: each row A[k][*] is traversed contiguously, and
         A[i][j] is updated in-place. For each fixed j, the sequence
         of arithmetic operations is identical to the original code
         (same order of subtractions), only the interleaving across
         different j values changes, which does not affect correctness.
      */
      for (k = 0; k < i; k++)
        {
          const DATA_TYPE Aik = Ai[k]; /* L(i,k), already computed. */
          DATA_TYPE *Ak = A[k];        /* Row k of U. */

          for (j = i; j < _PB_N; j++)
            Ai[j] -= Aik * Ak[j];
        }
    }

  /* Forward substitution: solve L * y = b.
     L has unit diagonal, stored in the strictly lower part of A.
  */
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE *Ai = A[i];
      w = b[i];

      for (j = 0; j < i; j++)
        w -= Ai[j] * y[j];

      y[i] = w;
    }

  /* Backward substitution: solve U * x = y.
     U is stored in the upper-triangular part of A (including diagonal).
  */
  for (i = _PB_N-1; i >= 0; i--)
    {
      DATA_TYPE *Ai = A[i];
      w = y[i];

      for (j = i+1; j < _PB_N; j++)
        w -= Ai[j] * x[j];

      x[i] = w / Ai[i];
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(b),
	      POLYBENCH_ARRAY(x),
	      POLYBENCH_ARRAY(y));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_ludcmp (n,
		 POLYBENCH_ARRAY(A),
		 POLYBENCH_ARRAY(b),
		 POLYBENCH_ARRAY(x),
		 POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(b);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}

