#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "ludcmp.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_1D(b,N,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;
  DATA_TYPE fn = (DATA_TYPE)n;

  /* Initialize vectors b, x, y.  This is O(n); cost is negligible
   * compared to the following O(n^3) SPD construction, so we leave
   * it in the simple scalar form for clarity. */
  for (i = 0; i < n; i++)
    {
      x[i] = 0;
      y[i] = 0;
      b[i] = (i+1)/fn/2.0 + 4;
    }

  /* Initialize A as a unit lower-triangular matrix with a simple
   * pattern in the strictly lower part. */
  for (i = 0; i < n; i++)
    {
      for (j = 0; j <= i; j++)
	A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++) {
	A[i][j] = 0;
      }
      A[i][i] = 1;
    }

  /* Make the matrix positive semi-definite.
   *
   * Original code:
   *   B = 0;
   *   for t
   *     for r
   *       for s
   *         B[r][s] += A[r][t] * A[s][t];
   *
   * This computes B = A * A^T.  Below we compute the *same* quantity
   * but with a loop ordering (r, s, t) that improves spatial
   * locality: the innermost loop walks along contiguous elements
   * A[r][t] and A[s][t].  We also compute each B[r][s] from scratch
   * using a local accumulator instead of repeated "+=" updates.  For
   * each fixed (r,s), the sequence of summed terms over t is the same
   * (t = 0..n-1), so floating-point results are bitwise identical to
   * the original code for each entry B[r][s].
   */

  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  /* Compute B = A * A^T with t as innermost loop to maximize cache
   * efficiency.  We intentionally do *not* exploit symmetry
   * (i.e., we do not set B[s][r] = B[r][s]) in order to preserve the
   * original per-entry floating-point reduction semantics. */
  for (r = 0; r < n; ++r)
  {
    DATA_TYPE *restrict Ar = A[r];
    for (s = 0; s < n; ++s)
    {
      DATA_TYPE *restrict As = A[s];
      DATA_TYPE sum = 0;
      for (t = 0; t < n; ++t)
      {
        sum += Ar[t] * As[t];
      }
      (POLYBENCH_ARRAY(B))[r][s] = sum;
    }
  }

  /* Copy B back into A.  Use row pointers to encourage the compiler
   * to generate tight, vectorizable code. */
  for (r = 0; r < n; ++r)
  {
    DATA_TYPE *restrict Arow = A[r];
    DATA_TYPE *restrict Brow = (POLYBENCH_ARRAY(B))[r];
    for (s = 0; s < n; ++s)
      Arow[s] = Brow[s];
  }

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x[i]);
  }
  POLYBENCH_DUMP_END("x");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_ludcmp[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(b,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j, k;
  DATA_TYPE w;

#pragma scop
  /* LU factorization without pivoting: A = L * U, with L stored in the
   * strict lower triangular part of A and U in the upper part including
   * the diagonal.  This is the same algorithm as in the original code;
   * we only cache row pointers (Ai) to improve data locality and reduce
   * address computation in the innermost loops. */
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *restrict Ai = A[i];

    /* Compute the L part (strictly lower triangular entries in row i). */
    for (j = 0; j < i; j++) {
      w = Ai[j];

      /* Dot product between row i and column j using previously
       * computed L and U entries:
       *   w -= sum_{k=0}^{j-1} A[i][k] * A[k][j]
       * The loop bounds and order are identical to the original code,
       * so floating-point semantics are preserved. */
      for (k = 0; k < j; k++) {
        w -= Ai[k] * A[k][j];
      }

      Ai[j] = w / A[j][j];
    }

    /* Compute the U part (diagonal and upper triangular entries
     * in row i). */
    for (j = i; j < _PB_N; j++) {
      w = Ai[j];

      /*   w -= sum_{k=0}^{i-1} A[i][k] * A[k][j]   */
      for (k = 0; k < i; k++) {
        w -= Ai[k] * A[k][j];
      }

      Ai[j] = w;
    }
  }

  /* Forward substitution: solve L * y = b.
