  for (i = _PB_N-1; i >= 0; i--) {
    DATA_TYPE *restrict Ai = A[i];
    w = y[i];

    for (j = i+1; j < _PB_N; j++)
      w -= Ai[j] * x[j];

    x[i] = w / Ai[i];
