     This narrows possible aliasing and enables better optimizations. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE *restrict b_ = b;
  DATA_TYPE *restrict x_ = x;
  DATA_TYPE *restrict y_ = y;

#pragma scop
  /* LU factorization without pivoting. */
  for (int i = 0; i < _PB_N; i++) {
    DATA_TYPE *restrict Ai = A_[i];

    /* Compute L entries in row i (columns 0..i-1). */
    for (int j = 0; j < i; j++) {
      DATA_TYPE w = Ai[j];
      DATA_TYPE *restrict Aj = A_[j];

      /* Inner product: w -= sum_{k=0..j-1} Ai[k] * Aj[k]
         Unrolled by a factor of 4 while preserving the exact order
         of floating-point operations (0,1,2,3,4,...) to keep
         semantics identical. */
      int k = 0;
      int limit = j & ~3; /* largest multiple of 4 <= j */
      for (; k < limit; k += 4) {
        w -= Ai[k]     * Aj[k];
        w -= Ai[k + 1] * Aj[k + 1];
        w -= Ai[k + 2] * Aj[k + 2];
        w -= Ai[k + 3] * Aj[k + 3];
      }
      for (; k < j; ++k) {
        w -= Ai[k] * Aj[k];
      }

      Ai[j] = w / Aj[j];
    }

    /* Compute U entries in row i (columns i..N-1). */
    for (int j = i; j < _PB_N; j++) {
      DATA_TYPE w = Ai[j];

      /* Inner product: w -= sum_{k=0..i-1} Ai[k] * A[k][j]
         Again, unrolled by 4 with preserved operation order. */
      int k = 0;
      int limit = i & ~3;
      for (; k < limit; k += 4) {
        DATA_TYPE *restrict Ak0 = A_[k];
        DATA_TYPE *restrict Ak1 = A_[k + 1];
        DATA_TYPE *restrict Ak2 = A_[k + 2];
        DATA_TYPE *restrict Ak3 = A_[k + 3];

        w -= Ai[k]     * Ak0[j];
        w -= Ai[k + 1] * Ak1[j];
        w -= Ai[k + 2] * Ak2[j];
        w -= Ai[k + 3] * Ak3[j];
      }
      for (; k < i; ++k) {
        w -= Ai[k] * A_[k][j];
      }

      Ai[j] = w;
    }
  }

  /* Forward substitution: solve L * y = b. */
  for (int i = 0; i < _PB_N; i++) {
    DATA_TYPE w = b_[i];
    DATA_TYPE *restrict Ai = A_[i];

    int j = 0;
    int limit = i & ~3;
    for (; j < limit; j += 4) {
      w -= Ai[j]     * y_[j];
      w -= Ai[j + 1] * y_[j + 1];
      w -= Ai[j + 2] * y_[j + 2];
      w -= Ai[j + 3] * y_[j + 3];
    }
    for (; j < i; ++j) {
      w -= Ai[j] * y_[j];
    }

    y_[i] = w;
  }

  /* Backward substitution: solve U * x = y. */
  for (int i = _PB_N - 1; i >= 0; i--) {
    DATA_TYPE w = y_[i];
    DATA_TYPE *restrict Ai = A_[i];

    int j_start = i + 1;
    int j_end   = _PB_N;

    /* Unroll j loop in blocks of 4 while preserving the natural
